//! Golden decision-log fixtures shared by Rust and TS (docs/testing.md §3.3).
//!
//! A case is `testdata/event-log/<case>.jsonl` (one event object per line) plus
//! `<case>.expected.json`, the result of `fold` (design/file-engine.md §5.1): an object with
//! `state` (group id to state), `done` and `undone` (seq stacks), and `corrupt` (`seq`,
//! `reason`) when the log breaks a precondition.
//!
//! The cases are generated by `golden_cases` (hand-written logs and expected folds, plus a few
//! generated sessions folded by its own model). `golden` writes the case files that are missing
//! and never touches one that exists: an existing file that differs from the generator is an
//! error, to be deleted by hand before regenerating (xtask never overwrites or removes).
//! `golden --check` writes nothing: it checks the files are well formed and paired, and that
//! they are exactly what the generator produces, with no other file in the folder. It does not
//! fold the logs: the Rust golden test (`crates/core/tests/golden.rs`, US-10) does, and the TS
//! reducer will in M3 (US-27). The event schema is owned by design/file-engine.md §5 and the
//! `culla_core::decisions::codec` docs.

use std::collections::BTreeSet;
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::Path;

use crate::golden_cases;
use crate::json::{self, Value};

pub(crate) const DIR: &str = "testdata/event-log";
const LOG: &str = ".jsonl";
const EXPECTED: &str = ".expected.json";

pub(crate) fn check(root: &Path) -> Result<(), String> {
    let dir = root.join(DIR);
    let entries = fs::read_dir(&dir).map_err(|e| format!("cannot read {DIR}/: {e}"))?;
    let mut logs = BTreeSet::new();
    let mut expected = BTreeSet::new();
    let mut problems = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        if let Some(case) = name.strip_suffix(EXPECTED) {
            expected.insert(case.to_owned());
        } else if let Some(case) = name.strip_suffix(LOG) {
            logs.insert(case.to_owned());
        } else {
            problems.push(format!("{DIR}/{name}: not a {LOG} or {EXPECTED} fixture"));
        }
    }
    if logs.is_empty() {
        problems.push(format!("{DIR}/: no {LOG} cases"));
    }
    for case in logs.symmetric_difference(&expected) {
        let missing = if logs.contains(case) { EXPECTED } else { LOG };
        problems.push(format!("{DIR}/{case}: {case}{missing} is missing"));
    }
    for case in logs.intersection(&expected) {
        problems.extend(check_log(&dir, case));
        problems.extend(check_expected(&dir, case));
    }
    let generated = golden_cases::all();
    let known: BTreeSet<&str> = generated.iter().map(|c| c.name.as_str()).collect();
    for case in logs.union(&expected) {
        if !known.contains(case.as_str()) {
            problems.push(format!(
                "{DIR}/{case}: not produced by the generator (stale or hand-made)"
            ));
        }
    }
    for c in &generated {
        for (file, want) in files(c) {
            match fs::read_to_string(dir.join(&file)) {
                Ok(have) if have == want => {}
                Ok(_) => problems.push(format!("{DIR}/{file} differs from the generator output")),
                Err(e) => problems.push(format!("{DIR}/{file}: {e}")),
            }
        }
    }
    problems.extend(check_listed(root, &known));
    if problems.is_empty() {
        println!(
            "{DIR}: {} golden case(s) well formed and match the generator",
            logs.len()
        );
        Ok(())
    } else {
        Err(format!(
            "golden fixtures have problems:\n  {}",
            problems.join("\n  ")
        ))
    }
}

/// The Rust golden test compiles the cases in (the core does no file I/O), so it lists them:
/// every generated case must appear there as `case!("<name>")`.
const RUST_TEST: &str = "crates/core/tests/golden.rs";

fn check_listed(root: &Path, known: &BTreeSet<&str>) -> Vec<String> {
    let text = match fs::read_to_string(root.join(RUST_TEST)) {
        Ok(t) => t,
        Err(e) => return vec![format!("{RUST_TEST}: {e}")],
    };
    known
        .iter()
        .filter(|name| !text.contains(&format!("case!(\"{name}\")")))
        .map(|name| format!("{RUST_TEST}: case {name} is not listed in CASES"))
        .collect()
}

/// A case's two files: (file name, text).
fn files(c: &golden_cases::Case) -> [(String, &str); 2] {
    [
        (format!("{}{LOG}", c.name), c.log.as_str()),
        (format!("{}{EXPECTED}", c.name), c.expected.as_str()),
    ]
}

/// Writes the case files that are missing; refuses, before writing anything, if an existing
/// one differs from the generator.
pub(crate) fn write(root: &Path) -> Result<(), String> {
    let dir = root.join(DIR);
    let generated = golden_cases::all();
    let mut missing = Vec::new();
    for c in &generated {
        for (file, want) in files(c) {
            match fs::read_to_string(dir.join(&file)) {
                Ok(have) if have == want => {}
                Ok(_) => {
                    return Err(format!(
                        "{DIR}/{file} exists and differs from the generator. xtask never \
                         overwrites or removes files: delete it by hand to regenerate"
                    ));
                }
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => missing.push((file, want)),
                Err(e) => return Err(format!("{DIR}/{file}: {e}")),
            }
        }
    }
    fs::create_dir_all(&dir).map_err(|e| format!("cannot create {DIR}/: {e}"))?;
    for (file, text) in &missing {
        let path = dir.join(file);
        let mut f = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
            .map_err(|e| format!("cannot create {DIR}/{file}: {e}"))?;
        f.write_all(text.as_bytes())
            .and_then(|()| f.sync_all())
            .map_err(|e| format!("cannot write {DIR}/{file}: {e}"))?;
        println!("wrote {DIR}/{file} ({} bytes)", text.len());
    }
    println!(
        "{DIR}: {} case(s), {} file(s) written",
        generated.len(),
        missing.len()
    );
    Ok(())
}

fn read(dir: &Path, file: &str) -> Result<String, String> {
    fs::read_to_string(dir.join(file)).map_err(|e| format!("{DIR}/{file}: {e}"))
}

/// JSON Lines: every line is one JSON object; the file is empty or ends with a newline.
pub(crate) fn check_log_text(text: &str) -> Result<usize, String> {
    if !text.is_empty() && !text.ends_with('\n') {
        return Err("does not end with a newline".into());
    }
    let mut events = 0;
    for (n, line) in text.lines().enumerate() {
        let line_no = n + 1;
        match json::parse(line) {
            Ok(Value::Object(_)) => events += 1,
            Ok(_) => return Err(format!("line {line_no}: not a JSON object")),
            Err(e) => return Err(format!("line {line_no}: {e}")),
        }
    }
    Ok(events)
}

pub(crate) fn check_expected_text(text: &str) -> Result<(), String> {
    let v = json::parse(text)?;
    match (v.get("state"), v.get("done"), v.get("undone")) {
        (Some(Value::Object(_)), Some(Value::Array(_)), Some(Value::Array(_))) => {}
        _ => return Err("needs \"state\" (object), \"done\" and \"undone\" (arrays)".into()),
    }
    match v.get("corrupt") {
        None => Ok(()),
        Some(c @ Value::Object(fields))
            if fields.len() == 2
                && matches!(c.get("seq"), Some(Value::Number(_)))
                && matches!(c.get("reason"), Some(Value::String(_))) =>
        {
            Ok(())
        }
        Some(_) => Err("\"corrupt\" needs exactly \"seq\" (number) and \"reason\" (string)".into()),
    }
}

fn check_log(dir: &Path, case: &str) -> Option<String> {
    let file = format!("{case}{LOG}");
    read(dir, &file)
        .and_then(|t| check_log_text(&t))
        .err()
        .map(|e| format!("{DIR}/{file}: {e}"))
}

fn check_expected(dir: &Path, case: &str) -> Option<String> {
    let file = format!("{case}{EXPECTED}");
    read(dir, &file)
        .and_then(|t| check_expected_text(&t))
        .err()
        .map(|e| format!("{DIR}/{file}: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn logs() {
        assert_eq!(check_log_text(""), Ok(0));
        assert_eq!(check_log_text("{\"seq\":1}\n{\"seq\":2}\n"), Ok(2));
        assert!(check_log_text("{\"seq\":1}").is_err());
        assert!(check_log_text("[1]\n").is_err());
        assert!(check_log_text("\n").is_err());
    }

    #[test]
    fn expected() {
        assert!(check_expected_text("{\"state\":{},\"done\":[],\"undone\":[]}\n").is_ok());
        assert!(check_expected_text("{\"state\":[],\"done\":[],\"undone\":[]}").is_err());
        assert!(check_expected_text("{}").is_err());
        let corrupt = |c: &str| {
            check_expected_text(&format!(
                "{{\"state\":{{}},\"done\":[],\"undone\":[],\"corrupt\":{c}}}"
            ))
        };
        assert!(corrupt("{\"seq\":2,\"reason\":\"undo_not_top\"}").is_ok());
        assert!(corrupt("{\"seq\":2}").is_err());
        assert!(corrupt("{\"seq\":\"2\",\"reason\":\"x\"}").is_err());
        assert!(corrupt("{\"seq\":2,\"reason\":\"x\",\"more\":1}").is_err());
        assert!(corrupt("[]").is_err());
    }

    #[test]
    fn committed_fixtures_are_well_formed() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        check(&root).unwrap();
    }
}
